// Shared preview mockup HTML (identical for all cards)
const previewMockup = `<div class="preview-mockup"><div class="preview-topbar"><div class="preview-dot"></div><div class="preview-dot"></div><div class="preview-dot"></div></div><div class="preview-body"><div class="preview-sidebar"><div class="preview-sidebar-bar active" style="width:80%"></div><div class="preview-sidebar-bar" style="width:65%"></div><div class="preview-sidebar-bar" style="width:90%"></div><div class="preview-sidebar-bar" style="width:50%"></div></div><div class="preview-main"><div class="preview-line title"></div><div class="preview-line" style="width:100%"></div><div class="preview-line" style="width:85%"></div><div class="preview-line" style="width:95%"></div></div><div class="preview-actions"><div class="preview-action"><div class="preview-action-dot"></div><div class="preview-action-line"></div></div><div class="preview-action"><div class="preview-action-dot"></div><div class="preview-action-line"></div></div><div class="preview-action"><div class="preview-action-dot"></div><div class="preview-action-line"></div></div></div></div></div>`;

function renderCards() {
  const grid = document.querySelector('.grid');
  if (!grid) return;
  
  grid.innerHTML = themes.map(t => {
    const targetAttr = t.target ? ` target="${t.target}"` : '';
    const tagsHtml = t.tags.map(tag => `<span class="tag">${tag}</span>`).join('');
    return `<a href="${t.href}" class="card"${targetAttr}>
      <div class="card-preview ${t.previewClass}" style="background:${t.gradient}">
        ${previewMockup}
      </div>
      <div class="card-info">
        <div class="card-name">${t.name}</div>
        <div class="card-desc">${t.desc}</div>
        <div class="card-tags">${tagsHtml}</div>
      </div>
    </a>`;
  }).join('');
}

document.addEventListener('DOMContentLoaded', renderCards);
